CREATE OR REPLACE FUNCTION check_resolution_trigger_fn()
RETURNS TRIGGER AS $$
DECLARE
    iii_val numeric;
BEGIN
    -- Check if the update is trying to mark the case as Resolved
    IF NEW.enf_actions->>'res_state' = 'Resolved' THEN
        -- Calculate Investigation Intensity Index
        SELECT (0.6 * rc.behav_score + 0.4 * rc.net_score) INTO iii_val
        FROM enforcement_actions ea
        JOIN market_conditions mc ON ea."REC_ENF" = mc."REC_PIN"
        JOIN reg_compliance rc ON mc."REC_PIN" = rc."REC_COMP"
        WHERE ea."REC_ENF" = OLD."REC_ENF";

        -- Block if III exceeds threshold of 75
        IF iii_val > 75 THEN
            RAISE EXCEPTION 'Cannot resolve case % - Investigation Intensity Index (%) exceeds threshold of 75', OLD."REC_ENF", iii_val;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

